print("Edition: signature")
import hashlib
contents = {"v3": "alpha,beta,gamma", "v7": "alpha,beta,delta"}
def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()[:16]
pinned = {"version": "v3", "hash": digest(contents["v3"])}
for ver, text in contents.items():
    print(ver, "hash", digest(text), "matches pin:", digest(text) == pinned["hash"])
print("RESULT pinned version verified by recomputed content hash")
